create table public.market_event_producer_evaluations(id uuid primary key default gen_random_uuid(),observation_id uuid references public.crypto_market_observations(id),asset_id uuid references public.assets(id),producer_type text not null,producer_version text not null,baseline_version text not null,baseline_observation_id uuid references public.crypto_market_observations(id),information_cutoff_at timestamptz not null,available_at timestamptz not null,status text not null check(status in('EVENT_EMITTED','NO_EVENT','UNAVAILABLE')),reason text,event_id text references public.event_outbox(event_id),details jsonb not null default'{}',evaluation_hash text not null unique,created_at timestamptz not null default now());
create or replace function public.prevent_market_producer_mutation()returns trigger language plpgsql as $$begin raise exception'Market producer evaluations are immutable';end$$;create trigger market_producer_evaluations_immutable before update or delete on public.market_event_producer_evaluations for each row execute function public.prevent_market_producer_mutation();alter table public.market_event_producer_evaluations enable row level security;grant all privileges on public.market_event_producer_evaluations to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events'));
